import { openPanelPopup } from '/app/app/panel-popups.js';
import { get, subscribe } from '/app/app/store.js';
import { mountReferralTools } from './referral-tools.js';

// Move live controls, preserving the app's wallet, auth and preference owners.
export function mountBottomUtilities() {
  const desktop = matchMedia('(min-width:1100px)');
  const homes = new Map();
  let initialized = false, settings, history, referralLoad, affiliateLoad, affiliateLayout;
  function move(node, parent) {
    if (!node || !parent || node.parentNode === parent) return;
    if (!homes.has(node)) {
      const anchor = document.createComment('Original control position');
      node.before(anchor);
      homes.set(node, anchor);
    }
    parent.append(node);
  }
  function closeSettings() {
    if (settings?.classList.contains('is-open')) settings.querySelector('[data-settings-close]').click();
  }
  function sync() {
    settings = document.querySelector('.nav-settings');
    const wallet = document.querySelector('#unav-wallet-app');
    // Retire these options in this preview, including its mobile settings menu.
    for (const selector of ['[data-bind="settings-mine-flip-button"]', '[data-hide-balances]', '[data-bounties-mode]']) {
      settings?.querySelector(selector)?.closest('.nav-settings__row')?.remove();
    }
    syncReferrals();
    if (!desktop.matches) {
      const mobileTabs = document.querySelector('.mpager-tabs');
      const mobileConnect = Boolean(wallet && mobileTabs && !get('connected.address'));
      if (document.body.classList.contains('site-bottom-utilities')) closeSettings();
      for (const [node, anchor] of homes) {
        if (node === wallet && mobileConnect) continue;
        if (anchor.nextSibling !== node) anchor.after(node);
      }
      if (mobileConnect) move(wallet, mobileTabs);
      document.body.classList.toggle('site-mobile-connect', mobileConnect);
      document.body.classList.remove('site-bottom-utilities');
      return;
    }
    document.body.classList.remove('site-mobile-connect');
    const rail = document.querySelector('.info-rail');
    const nav = rail?.querySelector('.info-rail__nav');
    const discord = document.querySelector('#unav-discord-app');
    const countdown = document.querySelector('[data-bind="nav-jackpot-countdown"]');
    if (!nav || !wallet || !settings || !discord) return;
    if (!initialized) {
      initialized = true;
      const discordMark = document.createElement('img');
      discordMark.src = new URL('./art/discord-mark.svg', import.meta.url).href;
      discordMark.alt = '';
      discordMark.className = 'site-discord-mark';
      discord.querySelector('svg')?.replaceWith(discordMark);
      const label = document.createElement('span');
      label.textContent = 'Settings';
      label.className = 'site-settings-label';
      settings.querySelector('#unav-settings').append(label);
      history = document.querySelector('[data-panel-open="history"]');
      history?.addEventListener('click', event => {
        if (!desktop.matches) return;
        event.stopPropagation();
        closeSettings();
        openPanelPopup('history', settings.querySelector('#unav-settings'));
      });
    }
    move(wallet, nav);
    move(settings, nav);
    move(discord, nav);
    // Keep the existing protocol clock ticking as its live node changes homes.
    move(countdown, nav);
    if (nav.firstElementChild !== discord) nav.prepend(discord);
    if (countdown && discord.nextElementSibling !== countdown) discord.after(countdown);
    if (nav.lastElementChild !== wallet) nav.append(wallet);
    if (settings.nextElementSibling !== wallet) wallet.before(settings);
    move(history, settings.querySelector('[data-bind="settings-actions"]'));
    // The referral card ordinarily loads on the first Games visit. Load its
    // existing owner here so Refer friends is available from the initial page.
    if (!referralLoad) {
      const sheet = document.querySelector('link[data-href="/app/styles/sacrifices.css"]');
      if (sheet && !sheet.hasAttribute('href')) sheet.href = sheet.dataset.href;
      referralLoad = import('/app/components/app-degenerette-panel.js');
      referralLoad.then(sync).catch(error => console.error('Referral card unavailable', error));
    }
    if (!document.body.classList.contains('site-bottom-utilities')) {
      document.body.classList.add('site-bottom-utilities');
      dispatchEvent(new Event('resize'));
    }
  }
  function syncReferrals() {
    const strip = document.querySelector('[data-referral-strip]');
    if (!strip?.querySelector('.deg-referral-card')) return;
    document.querySelector('[data-panel-open="referrals"]')?.remove();
    // Retire the popup host before upgrading the native component. Each layout
    // gets a fresh instance because its disconnect hook stops subscriptions.
    document.querySelector('#panel-referrals')?.remove();
    const layout = desktop.matches ? 'desktop' : 'mobile';
    if (affiliateLayout !== layout) {
      strip.querySelector('app-affiliate-panel')?.remove();
      const panel = document.createElement('app-affiliate-panel');
      panel.className = 'site-referrals-inline';
      strip.append(panel);
      strip.classList.add('site-referral-strip');
      affiliateLayout = layout;
      if (!affiliateLoad) affiliateLoad = import('/app/components/app-affiliate-panel.js').then(sync);
    }
    const details = strip.querySelector('[data-bind="aff-details"]');
    const active = !desktop.matches || document.body.dataset.desktopInfo === 'referrals';
    if (details && details.open !== active) details.open = active;
    mountReferralTools(strip);
  }
  // Observe only insertion/removal; native controls frequently update labels.
  let queued = false;
  new MutationObserver(() => {
    if (queued) return;
    queued = true;
    requestAnimationFrame(() => { queued = false; sync(); });
  }).observe(document.body, { childList: true, subtree: true });
  desktop.addEventListener('change', sync);
  document.addEventListener('desktop-info:change', sync);
  subscribe('connected.address', sync);
  sync();
}
